void dijkstra(vector<vector<int>> graph, vector<vector<int>> weights, vector<int> &distances, int n)
{
  // need a set to make the nodes visited
  // need a pq so that I can store the min distances

  vector<bool> visited(n, false);
  priority_queue<pair<int, int>> pq;
  // now I am gonna store the distances in negative so that I can make this work as a min
  // pq

  pq.push({-INT_MAX, 0}); // first is the distance and second is the actual node to which that distance is from source
  while(!pq.empty())
  {
     auto front = pq.top();
     pq.pop();

     auto parent = front.second; // we are currenly expanding this node
     visited[parent]=true; // I will be storing the weights in the first part of the pair so that the pq can sort them well
     for(auto i: graph[parent])
     {

      if(!visited[i] and distances[i]>distances[parent] + weights[parent][i])
      { 
        distances[i] = distances[parent] + weights[parent][i];
        pq.push({-distances[i],i});
      }


     }

  }

}
