#include <stdio.h>
#include <stdlib.h>
#include <math.h>

// Define the structure for a binary tree node
struct Node {
    int data;
    struct Node* left;
    struct Node* right;
};

// Define a structure to store balanced nodes and track count
struct BalancedNodes {
    struct Node** nodes; // Array of node pointers
    int count;          // Number of balanced nodes
    int capacity;       // Capacity of the array
};

// Create a new tree node
struct Node* newNode(int data) {
    struct Node* node = (struct Node*)malloc(sizeof(struct Node));
    node->data = data;
    node->left = NULL;
    node->right = NULL;
    return node;
}

// Initialize the balanced nodes list
struct BalancedNodes* initBalancedNodes(int capacity) {
    struct BalancedNodes* list = (struct BalancedNodes*)malloc(sizeof(struct BalancedNodes));
    list->nodes = (struct Node**)malloc(capacity * sizeof(struct Node*));
    list->count = 0;
    list->capacity = capacity;
    return list;
}

// Add a node to the balanced nodes list
void addBalancedNode(struct BalancedNodes* list, struct Node* node) {
    if (list->count >= list->capacity) {
        // Simple handling: in practice, resize the array
        printf("Balanced nodes array is full!\n");
        return;
    }
    list->nodes[list->count] = node;
    list->count++;
}

// Recursive function to compute height and check balance
int computeHeightAndCheckBalance(struct Node* node, struct BalancedNodes* balanced_nodes) {
    // Base case: empty subtree
    if (node == NULL) {
        return 0;
    }

    // Recursively compute left height
    int left_height = computeHeightAndCheckBalance(node->left, balanced_nodes);

    // Recursively compute right height
    int right_height = computeHeightAndCheckBalance(node->right, balanced_nodes);

    // Check if the node is properly balanced
    if (abs(left_height - right_height) <= 1) {
        addBalancedNode(balanced_nodes, node);
    }

    // Compute the height of the current node
    int height = 1 + (left_height > right_height ? left_height : right_height);

    return height;
}

// Main function to enumerate balanced nodes
void enumerateBalancedNodes(struct Node* root) {
    // Initialize balanced nodes list (assuming max n nodes)
    struct BalancedNodes* balanced_nodes = initBalancedNodes(100); // Adjust capacity as needed

    // Compute heights and collect balanced nodes
    computeHeightAndCheckBalance(root, balanced_nodes);

    // Print the balanced nodes
    printf("Properly balanced nodes (by data): ");
    if (balanced_nodes->count == 0) {
        printf("None\n");
    } else {
        for (int i = 0; i < balanced_nodes->count; i++) {
            printf("%d", balanced_nodes->nodes[i]->data);
            if (i < balanced_nodes->count - 1) {
                printf(", ");
            }
        }
        printf("\n");
    }

    // Free allocated memory
    free(balanced_nodes->nodes);
    free(balanced_nodes);
}

// Utility function to free the tree
void freeTree(struct Node* node) {
    if (node == NULL) {
        return;
    }
    freeTree(node->left);
    freeTree(node->right);
    free(node);
}

// Main function for testing
int main() {
    // Example tree:
    //       1
    //      / \
    //     2   3
    //    /
    //   4
    struct Node* root = newNode(1);
    root->left = newNode(2);
    root->right = newNode(3);
    root->left->left = newNode(4);

    enumerateBalancedNodes(root);

    // Free the tree
    freeTree(root);

    return 0;
}

