#include <stdio.h>
#include <stdlib.h>

void findSubset(int* S, int n, int k, int** T, int* T_size) {
    int* S_r[1000] = {0}; // Assume k <= 1000
    int S_r_sizes[1000] = {0};

    // Group elements
    for (int i = 0; i < n; i++) {
        int r = ((S[i] % k) + k) % k;
        if (!S_r[r]) S_r[r] = malloc(n * sizeof(int));
        S_r[r][S_r_sizes[r]++] = S[i];
    }

    // Initialize result
    *T_size = 0;
    *T = malloc(n * sizeof(int));

    // Handle remainder 0
    if (S_r_sizes[0] > 0) {
        (*T)[(*T_size)++] = S_r[0][0];
    }

    // Handle remainder k/2
    if (k % 2 == 0 && S_r_sizes[k/2] > 0) {
        (*T)[(*T_size)++] = S_r[k/2][0];
    }

    // Process pairs
    for (int i = 1; i <= (k - 1) / 2; i++) {
        int j = k - i;
        if (i == j) continue;
        if (S_r_sizes[i] > S_r_sizes[j]) {
            for (int x = 0; x < S_r_sizes[i]; x++) {
                (*T)[(*T_size)++] = S_r[i][x];
            }
        } else {
            for (int x = 0; x < S_r_sizes[j]; x++) {
                (*T)[(*T_size)++] = S_r[j][x];
            }
        }
    }

    // Clean up
    for (int i = 0; i < k; i++) {
        if (S_r[i]) free(S_r[i]);
    }
}

int main() {
    int S[] = {1, 2, 3, 4, 5, 6, 7, 8, 9};
    int n = 9, k = 3;
    int* T, T_size;

    printf("Input set S: ");
    for (int i = 0; i < n; i++) printf("%d ", S[i]);
    printf("\nk = %d\n", k);

    findSubset(S, n, k, &T, &T_size);

    printf("Subset T: ");
    for (int i = 0; i < T_size; i++) printf("%d ", T[i]);
    printf("\nSize of T: %d\n", T_size);

    free(T);
    return 0;
}

int findLoc (int *arr, int q) { 
   int i = 0, right, left;

   if (arr[i] == q) return i;

   for (i = 1; arr[i]!=-1; i = i*2) {
      if (arr[i] == q) return i;
      if (arr[i] > q) {
         break;
      }
   }

   right = i;
   left = i/2;
   while (right>=left) {
      int mid = (right + left) /2;
      if (arr[mid] == q) return mid;
      else if (arr[mid] > q || arr[mid] = -1) right = mid - 1;
      else left = mid + 1;
   }

   if (left > right) return -1;
}

