void Heapify(int* A, int i, int n) {
 int left=2*i+1;
 int right=2*i+2;
 int mid=i;

if (left<=n && right <=n) {
if ((A[left] > A[right] && A[left]< A[i]) || A[left]<A[right] && A[left] >A[i])
      mid=left;
else if((A[left<A[right] && A[right]<A[i]) || A[left]>A[right] && A[right]>A[i])
      mid=right;
else mid=i;
  }

  if (mid!=i) {
      swap(A[i], A[mid]);
      Heapify(A, mid, n);
   }
}
void Build_heap (int *A, int n) {
  int i=0;
  for (i=n; i>=0;i--) {
    Heapify(A, i, n);
  }
}

